onTagUpdated({ fire }) {
  const listener = async (event, key, changedValues, oldValues) => {
    if (fire.wakeup) {
      await fire.wakeup();
    }
    fire.async(key, changedValues, oldValues);
  };
  tagTracker.on("tag-updated", listener);
  return {
    unregister: () => {
      tagTracker.off("tag-updated", listener);
    },
    convert(newFire) {
      fire = newFire;
    },
  };
